public struct BalanceView {
    public var available: String
    public var immature: String
    public var pendingOut: String
    public var total: String
    public var tipHeight: UInt64
    public var scannedTo: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(available: String, immature: String, pendingOut: String, total: String, tipHeight: UInt64, scannedTo: UInt64) {
        self.available = available
        self.immature = immature
        self.pendingOut = pendingOut
        self.total = total
        self.tipHeight = tipHeight
        self.scannedTo = scannedTo
    }
}



extension BalanceView: Equatable, Hashable {
    public static func ==(lhs: BalanceView, rhs: BalanceView) -> Bool {
        if lhs.available != rhs.available {
            return false
        }
        if lhs.immature != rhs.immature {
            return false
        }
        if lhs.pendingOut != rhs.pendingOut {
            return false
        }
        if lhs.total != rhs.total {
            return false
        }
        if lhs.tipHeight != rhs.tipHeight {
            return false
        }
        if lhs.scannedTo != rhs.scannedTo {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(available)
        hasher.combine(immature)
        hasher.combine(pendingOut)
        hasher.combine(total)
        hasher.combine(tipHeight)
        hasher.combine(scannedTo)
    }
}


